package com.tihai.controller;
import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.scheduling.annotation.Scheduled;import com.tihai.utils.*;import com.tihai.common.R;import java.util.*;import java.io.*;import java.nio.file.*;import java.util.concurrent.*;
@RestController @RequestMapping("/local/signin") public class SigninController {
 @Autowired private AccountRegistry registry;@Autowired private SigninCatalog catalog;@Autowired private SigninStore store;@Autowired private SecurityAlertHub security;private final Map<String,Job> jobs=new ConcurrentHashMap<>();private final ExecutorService executor=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"ordinary-signin-worker");t.setDaemon(true);return t;});
 protected static class Job {final SigninCatalog.Entry entry;volatile String state="queued",message="签到已排队";volatile ExamBrowserSession browser;volatile Future<?> future;Job(SigninCatalog.Entry e){entry=e;}}
 protected ExamBrowserSession openBrowser(String id)throws IOException{return new ExamBrowserSession.ProcessSession(Paths.get("D:/tool/qita/SuperAutoStudy"),id,"signin-bridge.cjs");}
 private Map<String,Object> snapshot(Job j){Map<String,Object> m=new LinkedHashMap<>();m.put("state",j.state);m.put("message",j.message);return m;}
 @GetMapping("/list") public R list(){Map<String,Object> data=catalog.list();for(Map<String,Object> item:(List<Map<String,Object>>)data.get("items")){String id=String.valueOf(item.get("id"));Job j=jobs.get(id);Map<String,Object> record=j==null?store.record(id):snapshot(j);if(record!=null){record=new LinkedHashMap<>(record);if(j==null&&Arrays.asList("signing","queued","verification").contains(record.get("state"))){record.put("state","uncertain");record.put("message","上次签到中断，需核对平台状态，不会自动重试");}item.put("record",record);}}data.put("settings",store.settings());return R.ok().setData(data);}
 @GetMapping("/settings") public R settings(){return R.ok().setData(store.settings());}
 @PostMapping("/settings") public R saveSettings(@RequestBody Map<String,Object> body){try{Set<String> valid=new HashSet<>();for(Map<String,Object> c:(List<Map<String,Object>>)catalog.list().get("courses"))valid.add(String.valueOf(c.get("id")));List<String> keys=new ArrayList<>();for(Object item:(List<?>)body.getOrDefault("courseKeys",Collections.emptyList())){String id=String.valueOf(item);if(!valid.contains(id))return R.error(400,"课程选择已过期，请刷新");keys.add(id);}boolean enable=Boolean.TRUE.equals(body.get("autoNormal"));if(enable&&keys.isEmpty())return R.error(400,"请先勾选需要自动普通签到的课程");store.settings(enable,keys);return R.ok(enable?"已开启所选课程的自动普通签到":"已关闭自动普通签到").setData(store.settings());}catch(Exception e){return R.error(400,"签到设置保存失败");}}
 @Scheduled(fixedDelay=30000,initialDelay=15000) public void autoPoll(){if(registry!=null&&!AccountScope.scoped()){try{registry.refresh();for(Map<String,Object> a:registry.allChaoxing()){AccountScope.bind(a);try{pollSelected();}finally{AccountScope.clear();}}}catch(Exception ignored){}return;}pollSelected();}private void pollSelected(){try{Map<String,Object> config=store.settings();if(!Boolean.TRUE.equals(config.get("autoNormal")))return;Set<String> selected=new HashSet<>((List<String>)config.get("courseKeys"));if(selected.isEmpty())return;for(Map<String,Object> row:(List<Map<String,Object>>)catalog.list().get("items")){if(!Boolean.TRUE.equals(row.get("ongoing"))||!"normal".equals(row.get("kind"))||!selected.contains(row.get("courseKey"))||store.record(String.valueOf(row.get("id")))!=null)continue;enqueue(catalog.entry(String.valueOf(row.get("id"))));}}catch(Exception ignored){}}
 @PostMapping("/start") public R start(@RequestBody Map<String,Object> body){if(!Boolean.TRUE.equals(body.get("confirmed")))return R.error(400,"需要确认向平台发起普通签到");try{SigninCatalog.Entry e=catalog.entry(String.valueOf(body.get("id")));if(!e.ongoing)return R.error(409,"签到已经结束");if(!"normal".equals(e.kind))return R.error(400,"位置签到请使用手机App；其他签到方式需人工处理");return enqueue(e)?R.ok("普通签到已排队，遇到安全验证时将等待处理"):R.error(409,"已有签到记录，请先核对平台；不会重复提交");}catch(Exception e){return R.error(400,"签到入口不可用，请刷新");}}
 private synchronized boolean enqueue(SigninCatalog.Entry e)throws IOException{if(jobs.containsKey(e.id)||store.record(e.id)!=null)return false;Job j=new Job(e);Map<String,Object> record=snapshot(j);record.put("title",e.title);record.put("course",e.course);if(!store.claim(e.id,record))return false;jobs.put(e.id,j);j.future=executor.submit(()->run(j));return true;}
 protected Map<String,Object> init(Job j){SigninCatalog.Entry e=j.entry;Map<String,Object> cmd=new LinkedHashMap<>();cmd.put("op","init");cmd.put("url",e.url);cmd.put("courseId",e.courseId);cmd.put("classId",e.clazzId);cmd.put("activeId",e.activeId);cmd.put("kind",e.kind);String pf=System.getenv("ProgramFiles(x86)");cmd.put("edge",Paths.get(pf==null?"C:/Program Files (x86)":pf,"Microsoft/Edge/Application/msedge.exe").toString());List<Map<String,String>> cookies=new ArrayList<>();for(Map.Entry<String,String> c:CourseUtil.convertCookieStringToMap(catalog.auth().cookies(e.account)).entrySet()){Map<String,String> cookie=new LinkedHashMap<>();cookie.put("name",c.getKey());cookie.put("value",c.getValue());cookie.put("domain",".chaoxing.com");cookie.put("path","/");cookies.add(cookie);}cmd.put("cookies",cookies);return cmd;}
 protected String preflight(SigninCatalog.Entry e)throws Exception{return SigninCatalog.inspect(CourseExamCatalog.get(catalog.auth().session(e.account).initSession(false,false),e.url),e);}
 private void run(Job j){try{String ready=preflight(j.entry);if(!"ready".equals(ready)){j.state=ready;j.message="completed".equals(ready)?"平台已显示签到成功":"phone_required".equals(ready)?"平台要求手机App，未在电脑继续签到":"平台当前页面需要人工核对，未继续提交";store.result(j.entry.id,j.state,j.message);return;}j.state="signing";j.message="正在执行普通签到，等待平台确认";store.result(j.entry.id,j.state,j.message);j.browser=openBrowser(j.entry.id);j.browser.send(init(j));while(true){Map<String,Object> event=j.browser.read();String kind=String.valueOf(event.get("event"));if("verification".equals(kind)){j.state="verification";j.message=String.valueOf(event.get("message"));store.result(j.entry.id,j.state,j.message);security.raise("signin",j.entry.id,j.entry.title,j.message);continue;}if(!Arrays.asList("completed","phone_required","ended","uncertain","error").contains(kind))throw new IOException("签到返回阶段无法识别");j.state="error".equals(kind)?"uncertain":kind;j.message=String.valueOf(event.get("message"));store.result(j.entry.id,j.state,j.message);if("completed".equals(kind))security.resolve("signin",j.entry.id);catalog.invalidate();break;}}catch(Exception ex){if(!"stopped".equals(j.state)){j.state="uncertain";j.message="签到结果未确认，请核对平台；不会自动重复提交";}try{store.result(j.entry.id,j.state,j.message);}catch(Exception ignored){}}finally{security.resolve("signin",j.entry.id);if(j.browser!=null)j.browser.close();}}
 @PostMapping("/stop") public R stop(@RequestBody Map<String,String> body){Job j=jobs.get(body.get("id"));if(j==null||!Arrays.asList("queued","signing","verification").contains(j.state))return R.error(409,"当前没有可停止的签到任务");j.state="stopped";j.message="已停止等待；已提交的签到不能撤回，请核对平台";if(j.browser!=null)j.browser.close();if(j.future!=null)j.future.cancel(true);try{store.result(j.entry.id,j.state,j.message);}catch(Exception ignored){}return R.ok(j.message);}
 @PostMapping("/recheck") public R recheck(@RequestBody Map<String,String> body){try{SigninCatalog.Entry e=catalog.entry(body.get("id"));String status=preflight(e);if("completed".equals(status)){store.result(e.id,"completed","只读核对：平台已签到");security.resolve("signin",e.id);return R.ok("平台已确认签到成功");}return R.ok("已读取平台状态，尚未确认成功；没有发起新的签到").setData(Collections.singletonMap("state",status));}catch(Exception e){return R.error(400,"平台状态读取失败，未重新签到");}}
 @GetMapping("/locations") public R locations(){return R.ok().setData(store.locations());}
 @PostMapping("/locations/add") public R addLocation(@RequestBody Map<String,Object> body){try{return R.ok().setData(store.addLocation(String.valueOf(body.getOrDefault("name","")),Double.parseDouble(String.valueOf(body.get("latitude"))),Double.parseDouble(String.valueOf(body.get("longitude"))),String.valueOf(body.getOrDefault("address",""))));}catch(Exception ex){return R.error(400,ex instanceof IOException?ex.getMessage():"经纬度格式不正确");}}
 @PostMapping("/locations/delete") public R deleteLocation(@RequestBody Map<String,String> body){try{store.deleteLocation(body.get("id"));return R.ok("位置已删除");}catch(Exception e){return R.error(400,"位置删除失败");}}
 @PostMapping("/locations/export") public R export(){try{Map<String,Object> data=new LinkedHashMap<>();data.put("filename","学生通常用位置.gpx");data.put("contentBase64",Base64.getEncoder().encodeToString(store.exportGpx()));return R.ok().setData(data);}catch(Exception e){return R.error(400,"位置导出失败");}}
 @PostMapping("/locations/import") public R importGpx(@RequestBody Map<String,String> body){try{String data=body.getOrDefault("contentBase64","");if(data.length()>3*1024*1024)return R.error(400,"导入文件过大");return R.ok("已导入 "+store.importGpx(Base64.getDecoder().decode(data))+" 个WGS84位置点");}catch(Exception e){return R.error(400,e instanceof IOException?e.getMessage():"GPX文件格式不正确");}}
 @javax.annotation.PreDestroy public void shutdown(){for(Job j:jobs.values())if(j.browser!=null)j.browser.close();executor.shutdownNow();}
}
